#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){if(argc!=7){cerr<<"usage: model sequence restarts iterations maxhomophones output\n";return 1;}int A=24;vector<float> lm(A+A*A+A*A*A+A*A*A*A);ifstream in(argv[1],ios::binary);in.read((char*)lm.data(),lm.size()*4);if(!in)return 2;ifstream f(argv[2]);vector<int> seq;int v,K=0;while(f>>v){seq.push_back(v);K=max(K,v+1);}int restarts=stoi(argv[3]),iters=stoi(argv[4]),maxh=stoi(argv[5]);vector<int> k(K),cnt(A);mt19937 rng(731);uniform_real_distribution<double>U(0,1);auto score=[&](const vector<int>&k){double s=0;int p=0,a=0,b=0,c=0;for(int t:seq){if(t<0){p=0;continue;}int d=k[t],idx;if(p==0)idx=d;else if(p==1)idx=A+a*A+d;else if(p==2)idx=A+A*A+(a*A+b)*A+d;else idx=A+A*A+A*A*A+((a*A+b)*A+c)*A+d;s+=lm[idx];if(p==0)a=d;else if(p==1)b=d;else if(p==2)c=d;else{a=b;b=c;c=d;}p++;}return s;};
vector<pair<double,vector<int>>> all;for(int r=0;r<restarts;r++){fill(cnt.begin(),cnt.end(),0);for(int&i:k){do{i=rng()%A;}while(cnt[i]>=maxh);cnt[i]++;}double cur=score(k),best=cur;vector<int>bk=k;for(int it=0;it<iters;it++){int i=rng()%K,j=-1,old=k[i],nv;if(U(rng)<.60){j=rng()%K;nv=k[j];if(nv==old)continue;swap(k[i],k[j]);}else{nv=rng()%A;if(nv==old||cnt[nv]>=maxh)continue;k[i]=nv;cnt[old]--;cnt[nv]++;}double sc=score(k),T=2.5*pow(.02/2.5,double(it)/iters);if(sc>=cur||U(rng)<exp((sc-cur)/T)){cur=sc;if(cur>best){best=cur;bk=k;}}else{if(j>=0)swap(k[i],k[j]);else{k[i]=old;cnt[old]++;cnt[nv]--;}}}all.push_back({best,bk});}
sort(all.begin(),all.end(),[](auto&a,auto&b){return a.first>b.first;});ofstream out(argv[6]);string alpha="abcdefghiklmnopqrstuwxyz";for(int i=0;i<min(20,(int)all.size());i++){out<<setprecision(9)<<all[i].first<<'\t';for(int v:all[i].second)out<<alpha[v];out<<'\t';for(int t:seq)out<<(t<0?'|':alpha[all[i].second[t]]);out<<'\n';}cerr<<"K="<<K<<" best="<<all[0].first<<'\n';}
